function longestCommonPrefix(strs) {
  if (strs.length === 0) return '';
  let prefix = '';
  for (let c = 0; c < strs[0].length; c++) {
    const char = strs[0][c];
    for (let i = 1; i < strs.length; i++) {
      if (c >= strs[i].length || strs[i][c] !== char) {
        return prefix;
      }
    }
    prefix += char;
  }
  return prefix;
}

